// Verified Tajweed metadata (Hafs/Uthmani).
//
// Annotations are [start, end) character spans generated by the
// cpfair/quran-tajweed decision trees (Dar al-Maarifah references)
// run against OUR EXACT bundled Tanzil text — alignment by
// construction, never hand-shifted. Rendering only colors spans;
// the underlying verse text is never altered.

import 'dart:convert';

import 'package:flutter_riverpod/flutter_riverpod.dart';
import '../content/content_packages.dart';

class TajweedSpan {
  const TajweedSpan({
    required this.rule,
    required this.start,
    required this.end,
  });

  final String rule;
  final int start;
  final int end;
}

class TajweedRuleInfo {
  const TajweedRuleInfo({
    required this.rule,
    required this.nameAr,
    required this.nameEn,
    required this.colorValue,
  });

  final String rule;
  final String nameAr;
  final String nameEn;
  final int colorValue;
}

