TajweedRuleInfo ruleInfo(String rule) =>
    kTajweedRules.where((r) => r.rule == rule).firstOrNull ??
    TajweedRuleInfo(
        rule: rule,
        nameAr: rule,
        nameEn: rule,
        colorValue: 0xFF757575);

/// Pure span builder: clamps out-of-range annotations defensively
/// (logged by tests) and never mutates text.
List<({int start, int end, String? rule})> buildTajweedSegments(
    String text, List<TajweedSpan> spans) {
  final points = <int>{0, text.length};
  for (final s in spans) {
    final a = s.start.clamp(0, text.length);
    final b = s.end.clamp(0, text.length);
    if (a < b) {
      points.add(a);
      points.add(b);
    }
  }
  final sorted = points.toList()..sort();
  final out = <({int start, int end, String? rule})>[];
  for (var i = 0; i < sorted.length - 1; i++) {
    final a = sorted[i];
    final b = sorted[i + 1];
    String? rule;
    for (final s in spans) {
      if (s.start <= a && b <= s.end) {
        rule = s.rule;
        break;
      }
    }
    out.add((start: a, end: b, rule: rule));
  }
  return out;
}

/// ayah → spans for one surah (Hafs/Uthmani Tajweed only).
final tajweedSurahProvider =
    FutureProvider.family<Map<int, List<TajweedSpan>>, int>(
        (ref, surah) async {
  ref.watch(contentRevisionProvider);
  try {
    if (!await ContentPackageStore.instance
        .isInstalled('quran:tajweed-hafs')) {
      return const {};
    }
    final raw = await ContentPackageStore.instance.loadString(
      'assets/quran/tajweed/hafs/$surah.json',
    );
    final json = jsonDecode(raw) as Map<String, dynamic>;
    final out = <int, List<TajweedSpan>>{};
    for (final e in (json['entries'] as List)) {
      final m = e as Map<String, dynamic>;
      out[(m['ayah'] as num).toInt()] = [
        for (final a in (m['annotations'] as List))
          TajweedSpan(
            rule: (a as Map<String, dynamic>)['rule'] as String,
            start: ((a)['start'] as num).toInt(),
            end: ((a)['end'] as num).toInt(),
          ),
      ];
    }
    return out;
  } catch (_) {
    return const {};
  }
});
